    fun spec(id: CharacterId): CharacterArtSpec = specs.getValue(id)

    fun pose(id: CharacterId, state: CharacterState): CharacterStatePose {
        val m = spec(id).motion
        return when (state) {
            CharacterState.Idle, CharacterState.Hidden -> CharacterStatePose(0f, 0f, 1f, 0f, 0f, 0f, 1f)
            CharacterState.Typing -> CharacterStatePose(1.5f, m.typingTiltDeg, 1f, m.typingAccentDeg, 0f, m.typingGazeY, 1f)
            CharacterState.Thinking -> CharacterStatePose(-2f, m.thinkingTiltDeg, 1f, m.thinkingAccentDeg, m.thinkingGazeX, -2.5f, 1f)
            CharacterState.Responding -> CharacterStatePose(-1f, m.respondingTiltDeg, 1.015f, m.respondingAccentDeg, 0f, 1.5f, 1f)
            CharacterState.Completed -> CharacterStatePose(m.completedNodY * 0.4f, 1.2f, 1.02f, m.completedAccentDeg, 0f, 0f, 0.72f)
            CharacterState.Error -> CharacterStatePose(m.errorDropY, m.errorTiltDeg, 0.985f, m.errorAccentDeg, 0f, 3.5f, 0.82f)
        }
    }
}

/** Semantic state priority: Hidden > Error > Responding > Thinking > Completed > Typing > Idle. */
fun resolveCharacterState(
    hidden: Boolean = false,
    hasError: Boolean = false,
    isResponding: Boolean = false,
    isThinking: Boolean = false,
    isCompleted: Boolean = false,
    isTyping: Boolean = false,
): CharacterState = when {
    hidden -> CharacterState.Hidden
    hasError -> CharacterState.Error
    isResponding -> CharacterState.Responding
    isThinking -> CharacterState.Thinking
    isCompleted -> CharacterState.Completed
    isTyping -> CharacterState.Typing
    else -> CharacterState.Idle
}

/** Maps real UI turn signals to CharacterState; stopping immediately exits Thinking/Responding. */
fun deriveTurnCharacterState(
    isBusy: Boolean,
    isStopping: Boolean = false,
    hasOutput: Boolean = false,
    outcome: CharacterOutcome? = null,
    isTyping: Boolean = false,
    hidden: Boolean = false,
): CharacterState {
    val active = isBusy && !isStopping
    return resolveCharacterState(
        hidden = hidden,
        hasError = outcome == CharacterOutcome.Error,
        isResponding = active && hasOutput,
        isThinking = active && !hasOutput,
        isCompleted = !active && outcome == CharacterOutcome.Completed,
        isTyping = isTyping,
    )
}
